package app.cryptoresearch.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** App-owned native styling inspired by public One UI layout principles. */
public final class OneUi {
 public static final String PREF="ui-style",MODE="appearance";
 public static int dp(Context c,float x){return (int)(c.getResources().getDisplayMetrics().density*x+.5f);}
 public static boolean dark(Context c){return (c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;}
 public static int bg(Context c){return Color.parseColor(dark(c)?"#08090B":"#F3F4F7");}
 public static int surface(Context c){return Color.parseColor(dark(c)?"#191B20":"#FFFFFF");}
 public static int ink(Context c){return Color.parseColor(dark(c)?"#F5F6FA":"#171A21");}
 public static int muted(Context c){return Color.parseColor(dark(c)?"#B4BBC9":"#596274");}
 public static int blue(Context c){return Color.parseColor(dark(c)?"#8DBAFF":"#1456C7");}
 public static int tonal(Context c){return Color.parseColor(dark(c)?"#253348":"#E8EEFA");}
 public static int horizontal(Context c){return Math.max(20,(c.getResources().getConfiguration().screenWidthDp-760)/2);}
 public static GradientDrawable round(Context c,int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
 public static void surface(LinearLayout c){c.setPadding(dp(c.getContext(),20),dp(c.getContext(),20),dp(c.getContext(),20),dp(c.getContext(),20));c.setBackground(round(c.getContext(),surface(c.getContext()),28));}
 public static TextView text(Context c,String value,int size,boolean secondary){TextView t=new TextView(c);t.setText(value);t.setTextSize(size);t.setTextColor(secondary?muted(c):ink(c));t.setPadding(0,dp(c,4),0,dp(c,4));return t;}
 public static void button(Button b){Context c=b.getContext();b.setAllCaps(false);b.setTextSize(15);b.setTextColor(blue(c));b.setMinHeight(dp(c,52));b.setPadding(dp(c,16),dp(c,12),dp(c,16),dp(c,12));b.setBackgroundTintList(null);b.setBackground(new RippleDrawable(ColorStateList.valueOf(tonal(c)),round(c,tonal(c),24),null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(c,6);p.bottomMargin=dp(c,6);b.setLayoutParams(p);}
 public static void primary(Button b){Context c=b.getContext();b.setTextColor(dark(c)?Color.rgb(15,30,52):Color.WHITE);b.setBackgroundTintList(ColorStateList.valueOf(blue(c)));}
 public static LinearLayout header(Context c,String title,String detail){LinearLayout h=new LinearLayout(c);h.setOrientation(LinearLayout.VERTICAL);h.setGravity(Gravity.BOTTOM);h.setMinimumHeight(dp(c,c.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE?96:176));h.setPadding(dp(c,4),dp(c,20),dp(c,4),dp(c,24));TextView name=text(c,title,38,false);name.setTypeface(null,Typeface.BOLD);if(android.os.Build.VERSION.SDK_INT>=28)name.setAccessibilityHeading(true);h.addView(name);if(!detail.isEmpty())h.addView(text(c,detail,14,true));return h;}
 public static void confirm(Activity a,String title,String detail,Runnable action){AlertDialog dialog=new AlertDialog.Builder(a).setTitle(title).setMessage(detail).setNegativeButton("취소",(d,w)->{}).setPositiveButton("새 모의세션 시작",(d,w)->action.run()).create();dialog.setOnShowListener(v->{Window w=dialog.getWindow();if(w!=null){w.setGravity(Gravity.BOTTOM);w.setBackgroundDrawable(round(a,surface(a),28));w.setLayout(-1,-2);}});dialog.show();}
 public static LinearLayout navigation(Activity a,int selected,Runnable[] actions){LinearLayout nav=new LinearLayout(a);nav.setGravity(Gravity.CENTER);nav.setPadding(0,dp(a,6),0,dp(a,6));nav.setBackground(round(a,surface(a),28));String[] labels={"마켓","관심","연구실","설정"};for(int i=0;i<4;i++){final int index=i;LinearLayout item=new LinearLayout(a);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);item.setMinimumHeight(dp(a,64));item.setPadding(0,dp(a,6),0,dp(a,6));item.setSelected(i==selected);item.setContentDescription(labels[i]);item.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);item.setFocusable(true);item.setClickable(true);item.setOnClickListener(v->actions[index].run());item.setBackground(round(a,i==selected?tonal(a):surface(a),24));ImageView icon=new ImageView(a);icon.setImageDrawable(new NavIcon(i,i==selected?blue(a):muted(a)));icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);item.addView(icon,new LinearLayout.LayoutParams(dp(a,24),dp(a,24)));TextView label=text(a,labels[i],12,true);label.setTextColor(i==selected?blue(a):muted(a));label.setTypeface(null,i==selected?Typeface.BOLD:Typeface.NORMAL);label.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);item.addView(label);nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));}return nav;}
 static final class NavIcon extends Drawable {final int kind,color;final Paint p=new Paint(3);NavIcon(int k,int c){kind=k;color=c;}public void draw(Canvas c){c.save();c.translate(getBounds().left,getBounds().top);c.scale(getBounds().width()/24f,getBounds().height()/24f);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);Path path=new Path();if(kind==0){path.moveTo(3,4);path.lineTo(3,21);path.lineTo(22,21);path.moveTo(6,15);path.lineTo(11,10);path.lineTo(15,13);path.lineTo(21,5);}else if(kind==1){for(int i=0;i<10;i++){double angle=-Math.PI/2+i*Math.PI/5;float radius=i%2==0?10:4.6f;float x=12+(float)Math.cos(angle)*radius,y=12+(float)Math.sin(angle)*radius;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();}else if(kind==2){path.moveTo(8,3);path.lineTo(16,3);path.moveTo(10,3);path.lineTo(10,10);path.lineTo(4,20);path.quadTo(4,22,7,22);path.lineTo(17,22);path.quadTo(20,22,20,20);path.lineTo(14,10);path.lineTo(14,3);path.moveTo(7,16);path.lineTo(17,16);}else{for(int i=0;i<3;i++){float y=5+i*7;c.drawLine(3,y,21,y,p);c.drawCircle(i%2==0?8:16,y,2.5f,p);}}c.drawPath(path,p);c.restore();}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
 private OneUi(){}
}
